#define PROTO_ZODIAC    2
#define PROTO_GEOSTAR   3
#define PROTO_NAVCOM    4
#define PROTO_NMEA      5
#define PROTO_RTCM3     6
#define PROTO_TSIP      7
#define PROTO_GREIS     8
#define PROTO_SKYTRAQ   9
#define PROTO_COUNT     10

// Global session for reuse across fuzzer iterations
